public void process(METRebateCombinedContract _contract)
{
    // Extension point: allow recurring schedules to roll the date range forward on each run.
    this.adjustingDateRange(_contract);

    container allDeals = METRebateCombinedFlow::enumerateDealRecIds(_contract.parmQuery());

    // maxBatchTaskNum: 0 = auto (all available batch sessions), 1 = single-thread, >1 = that many (capped).
    int requestedTasks = _contract.parmMaxBatchTaskNum();

    boolean multiThread = BatchHeader::isExecutingInBatch()
                       && requestedTasks != 1
                       && conLen(allDeals) > 1;

    if (!multiThread)
    {
        // Requirement 1 - single sequential job over the whole selection.
        METRebateCombinedFlow::runForDeals(
            allDeals,
            _contract.parmFromDate(),
            _contract.parmToDate(),
            _contract.parmTransDate(),
            _contract.parmProcessRebate(),
            _contract.parmProcessWriteOff());
        return;
    }

    // Requirement 2 - parallel create-trans per deal bucket with single-threaded posting,
    // wired as a batch task DAG (create -> post barrier per transaction type).
    METRebateCombinedSplitTask splitTask =
        METRebateCombinedSplitTask::construct(requestedTasks);

    splitTask.parmDates(_contract.parmFromDate(), _contract.parmToDate(), _contract.parmTransDate());
    splitTask.parmScope(_contract.parmProcessRebate(), _contract.parmProcessWriteOff());
    splitTask.addDeals(allDeals);
    splitTask.spawnCombinedBatchTasks();
}

/// <summary>
/// Extension point for recurring schedules. Subscribers may adjust the contract's
/// From/To/Trans dates (via its parm setters) to advance the reporting period on each run.
/// Default: no adjustment - the dates entered in the dialog are used as-is.
/// </summary>
delegate void adjustingDateRange(METRebateCombinedContract _contract)
{
}
